with g as (select id, produtos_op from producao where data='2026-11-19' and linha='Linha 3' and produto='GeoPlus 20Kg'),
n as (select g.id, (select jsonb_agg(case when e->>'produto'='GeoPlus 20Kg' then e || jsonb_build_object('total_sacos',1585,'sacos_pallets',1585,
   'pallets', (select jsonb_agg(x) from (select jsonb_build_object('cap',c,'qtd',1585/c,'total',(1585/c)*c) x where 1585/c>0 union all select jsonb_build_object('cap',1585%c,'qtd',1,'total',1585%c,'parcial',true) where 1585%c>0) z))
   else e end) from jsonb_array_elements(g.produtos_op) e, lateral (select coalesce(((g.produtos_op->0->'pallets'->0->>'cap')::int),65) c) cc) po from g)
update producao p set produtos_op=n.po, total_sacos=1585, obs=coalesce(p.obs,'')||' · 23/11: planilha corrigiu para 1.585', atualizado_em=now() from n where p.id=n.id returning p.id;
