do $$ declare a record; s numeric; begin
 for a in select * from _alvo order by d loop
  select coalesce(sum(case when tipo in ('entrada','devolucao','retorno') then quantidade when tipo in ('consumo','perda','saida','doacao') then -quantidade when tipo='ajuste' then quantidade else 0 end),0)
    into s from insumos_movimentos where insumo_id=a.ins and data<=a.d;
  if abs(a.est - s) >= 0.0005 then
   insert into insumos_movimentos (insumo_id,data,tipo,quantidade,origem,responsavel,motivo,obs)
   values (a.ins,a.d,'ajuste',round(a.est-s,4),'INVENTARIO','Heliton José de Almeida Rodrigues','Conferência com o fechamento diário',
     'Acerto com o Controle Diário de Insumos de '||to_char(a.d,'DD/MM')||' (planilha: '||a.est||'; sistema: '||round(s,4)||')');
  end if;
 end loop; end $$;
